"""Lay students out in seating rows."""

from typing import List, Sequence

from rosterkit.models import Student


def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.casefold(),
        student.first_name.casefold(),
        student.student_id
    )


def _format_row(number: int, group: list) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"


def _check(students: Sequence[Student], seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _build_rows(ordered, seats) -> List[str]:
    lines = []
    for start in range(0, len(ordered), seats):
        group = ordered[start:start + seats]
        number = start // seats + 1
        lines.append(_format_row(number, group))
    return lines


def seat_rows(
    students: Sequence[Student], seats: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    return _build_rows(ordered, seats)

