import unittest

from rosterkit.models import Student
from rosterkit.seating import seat_rows


def make(last, first, ident="1"):
    return Student(ident, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make("Halloway", "Juno", "2"),
            make("Dunmere", "Piet", "1"),
            make("Ainsley", "Cole", "3")
        ]

    def test_sorted_and_split_into_rows(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(lines, [
            "Row 1: Ainsley, Cole | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(self.students, 10)
        self.assertEqual(len(lines), 1)
        self.assertIn("Row 1: Ainsley", lines[0])

    def test_sort_ignores_case_and_uses_first_name(self):
        pair = [make("smith", "Zed"), make("Smith", "Amy")]
        lines = seat_rows(pair, 2)
        self.assertEqual(
            lines, ["Row 1: Smith, Amy | smith, Zed"]
        )

    def test_input_is_not_modified(self):
        before = list(self.students)
        seat_rows(self.students, 2)
        self.assertEqual(self.students, before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 4)
